Item.method_code:
	return ProcessMethodLogic(CCO.Permissions, Aras.Server.Security.Identity.GetByName("Super User"));
}

internal Item ProcessMethodLogic(Aras.Server.Core.Abstractions.IPermissions permissions, Aras.Server.Security.Identity superUser)
{
	string favoriteId = this.getID();
	string teamId = this.getProperty("team_id");
	if (string.IsNullOrEmpty(teamId))
	{
		using (permissions.GrantIdentity(superUser))
		{

			var teamItem = this.newItem("Team", "add");
			teamItem.setProperty("name", favoriteId);
			teamItem.setProperty("is_system", "1");
			teamItem = teamItem.apply();
			if (teamItem.isError())
			{
				return teamItem;
			}
			teamId = teamItem.getID();
		}

	}
	this.setProperty("team_id", teamId);

	return this;
